public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int H = sc.nextInt(), W = sc.nextInt(), N = sc.nextInt();
        char[][] grid = new char[H+2][W+2];

        for (int i = 1; i <= H; i++) {
            String line = sc.next();
            for (int j = 1; j <= W; j++) {
                grid[i][j] = line.charAt(j-1);
            }
        }

        List<int[]> lastRoute = null;

        for (int walk = 1; walk <= N; walk++) {
            List<int[]> route = new ArrayList<>();
            int r = 1, c = 1;
            route.add(new int[]{r, c});

            while (r <= H && c <= W) {
                char dir = grid[r][c];
                if (dir == 'E') {
                    grid[r][c] = 'S';
                    c++;
                } else {
                    grid[r][c] = 'E';
                    r++;
                }
                route.add(new int[]{r, c});
            }

            if (walk == N) {
                lastRoute = route;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int[] pos : lastRoute) {
            sb.append(pos[0]).append(" ").append(pos[1]).append("\n");
        }
        System.out.print(sb);
    }
}

