public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int H = fs.nextInt();
        int W = fs.nextInt();
        long N = fs.nextInt();

        int[][] dir = new int[H + 2][W + 2];
        for (int i = 1; i <= H; i++) {
            for (int j = 1; j <= W; j++) {
                dir[i][j] = fs.nextInt(); // 0: East, 1: South
            }
        }

        // cnt[i][j] = number of times first (N-1) walks visit cell (i,j)
        long[][] cnt = new long[H + 2][W + 2];
        cnt[1][1] = N - 1;

        for (int i = 1; i <= H; i++) {
            for (int j = 1; j <= W; j++) {
                long x = cnt[i][j];
                if (x == 0) continue;

                if (dir[i][j] == 0) { // initially East
                    // visits alternate: East, South, East, South, ...
                    cnt[i][j + 1] += (x + 1) / 2;
                    cnt[i + 1][j] += x / 2;
                } else { // initially South
                    // visits alternate: South, East, South, East, ...
                    cnt[i + 1][j] += (x + 1) / 2;
                    cnt[i][j + 1] += x / 2;
                }
            }
        }

        // Simulate the N-th walk using the board state after N-1 walks.
        int r = 1, c = 1;
        while (r <= H && c <= W) {
            int current = dir[r][c];
            if ((cnt[r][c] & 1L) == 1L) current ^= 1; // toggled odd times after N-1 walks

            if (current == 0) c++; // East
            else r++;              // South
        }

        System.out.println(r + " " + c);
    }
}

