#include <stdio.h>

typedef long long ll;

const ll INF = 1e18;

ll binom(int n, int k) {
    if (k < 0 || k > n) return 0;
    if (k > n - k) k = n - k;
    ll res = 1;
    for (int i = 1; i <= k; i++) {
        if (res > INF / (n - k + i)) return INF + 1; // overflow
        res = res * (n - k + i) / i;
    }
    return res;
}

int main() {
    int H, W;
    ll N;
    scanf("%d %d %lld", &H, &W, &N);

    int r = H - 1, c = W - 1;
    ll ways = binom(r + c, r);
    if (ways > INF) ways = INF + 1; // cap

    while (r > 0 && c > 0) {
        if (N > ways) {
            putchar('S');
            N -= ways;
            ways = ways * r / (r + c);
            r--;
        } else {
            putchar('E');
            ways = ways * c / (r + c);
            c--;
        }
    }
    while (r > 0) {
        putchar('S');
        r--;
    }
    while (c > 0) {
        putchar('E');
        c--;
    }
    putchar('\n');
    return 0;
}

